    op.execute(sa.text("CREATE OR REPLACE FUNCTION validate_custody_chain_link()\nRETURNS trigger AS $$\nDECLARE\n    latest_id uuid;\nBEGIN\n    SELECT id INTO latest_id\n    FROM chain_of_custody\n    WHERE evidence_id = NEW.evidence_id\n    ORDER BY occurred_at DESC, created_at DESC, id DESC\n    LIMIT 1;\n\n    IF latest_id IS NULL AND NEW.previous_record_id IS NOT NULL THEN\n        RAISE EXCEPTION 'first custody record cannot reference a previous record';\n    END IF;\n\n    IF latest_id IS NOT NULL AND NEW.previous_record_id IS DISTINCT FROM latest_id THEN\n        RAISE EXCEPTION 'custody record must reference the latest record for this evidence';\n    END IF;\n\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql"))
